# Generated by tools/render_controls.py — edit the data files, not this file.
#
# Rule:        CKV2_AWS_56 (checkov 3.3.16)
# Applies to:  aws_iam_policy_attachment
# Read with:   aws_iam_policy(policy_arn: "arn:#{input('aws_partition')}:iam::aws:policy/IAMFullAccess") — an account-level singleton, so there is nothing to enumerate
#
# The rule id is the identity: file name, control id and `tag checkov_id` all
# carry it, and tools/lint_catalog_drift.py asserts the three agree.

control 'CKV2_AWS_56' do
  title 'Ensure AWS Managed IAMFullAccess IAM policy is not used'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the account's own aws_iam_policy_attachment, which is a single object
    rather than a collection.
  DESC

  desc 'rationale', <<~RATIONALE
    IAMFullAccess grants unrestricted iam:* — the ability to create a role,
    attach AdministratorAccess to it and assume it. Any principal holding it
    is effectively an account administrator regardless of what its other
    policies say, so the policy is a privilege-escalation path rather than a
    permission set. Least privilege is asserted here as "nothing is attached
    to it at all", which is the only state that can be checked without
    evaluating every attached principal's intent.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: Ensure AWS Managed IAMFullAccess IAM policy is not
    used.
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_iam_policy_attachment:

      # Replace the AWS-managed IAMFullAccess attachment with a customer-managed
      # policy scoped to the paths and actions the principal actually needs.
      resource "aws_iam_policy" "iam_admin_scoped" {
        name        = "iam-admin-scoped"
        description = "IAM administration limited to the service-role path"

        policy = jsonencode({
          Version = "2012-10-17"
          Statement = [{
            Effect   = "Allow"
            Action   = ["iam:CreateRole", "iam:DeleteRole", "iam:AttachRolePolicy",
                        "iam:DetachRolePolicy", "iam:TagRole"]
            Resource = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/service-role/*"
            Condition = {
              ArnLike = {
                "iam:PolicyARN" = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:policy/*"
              }
            }
          }]
        })
      }

      resource "aws_iam_role_policy_attachment" "platform_iam_admin" {
        role       = aws_iam_role.platform.name
        policy_arn = aws_iam_policy.iam_admin_scoped.arn
      }

    Out of band — aws_iam_policy_attachment:

      # Find every principal holding it, then detach each one.
      aws iam list-entities-for-policy --policy-arn arn:aws:iam::aws:policy/IAMFullAccess
      aws iam detach-role-policy --role-name <role> --policy-arn arn:aws:iam::aws:policy/IAMFullAccess
      aws iam detach-user-policy --user-name <user> --policy-arn arn:aws:iam::aws:policy/IAMFullAccess
      aws iam detach-group-policy --group-name <group> --policy-arn arn:aws:iam::aws:policy/IAMFullAccess

    Note (aws_iam_policy_attachment): Detach last, not first: a principal that
    administers IAM through this policy may be the only principal able to create
    its replacement. Also check permission sets — an attachment made through IAM
    Identity Center is re-provisioned onto the AWSReservedSSO_* role after any
    manual detach, so it must be removed at the permission set
    (aws_ssoadmin_managed_policy_attachment) or it comes straight back.
  FIX

  tag checkov_id:            'CKV2_AWS_56'
  tag checkov_category:      'IAM'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'graph'
  tag tf_resources:          %w[aws_iam_group_policy_attachment aws_iam_policy_attachment aws_iam_role aws_iam_role_policy_attachment aws_iam_user_policy_attachment aws_ssoadmin_managed_policy_attachment]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/iam_policy_attachment'
  tag nist:                  ['AC-3', 'AC-6']
  tag nist_r4:               ['AC-3', 'AC-6']
  tag cci:                   ['CCI-000213', 'CCI-002233']
  tag ksi:                   ['KSI-IAM-CTL']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  subject_resource = aws_iam_policy(policy_arn: "arn:#{input('aws_partition')}:iam::aws:policy/IAMFullAccess")

  # Always applicable. An account with no policy at all is the NON-COMPLIANT
  # state for this rule, not an inapplicable one — rendering it Not Applicable
  # would report the worst case as "does not apply here".
  impact 0.7

  describe 'aws_iam_policy_attachment' do
    it 'is configured for this account' do
      expect(subject_resource.exists?).to eq(true),
        'no account-level policy is set, so nothing constrains this'
    end
  end

  if subject_resource.exists?
    describe subject_resource do
      its('attachment_count') { should eq 0 }
    end
  end
end
